gaVp(){return"\uc774 \uae30\uae30\uc5d0\uc11c\ub294 \uc571 \ub0b4 \ucd2c\uc601\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc5c6\uc5b4\uc694."},
gaV8(){return"\uce74\uba54\ub77c \uad8c\ud55c\uc774 \ud544\uc694\ud574\uc694. \uc124\uc815\uc5d0\uc11c \uad8c\ud55c\uc744 \ud5c8\uc6a9\ud55c \ub4a4 \ub2e4\uc2dc \uc2dc\ub3c4\ud574 \uc8fc\uc138\uc694."},
gaVo(){return"\uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \uce74\uba54\ub77c\ub97c \ucc3e\uc9c0 \ubabb\ud588\uc5b4\uc694."},
gWv(){return"\ucd2c\uc601\uc744 \uc2dc\uc791\ud558\uc9c0 \ubabb\ud588\uc5b4\uc694. \uce74\uba54\ub77c \uc0c1\ud0dc\ub97c \ud655\uc778\ud55c \ub4a4 \ub2e4\uc2dc \uc2dc\ub3c4\ud574 \uc8fc\uc138\uc694."},
